r"""
Crescopus - Help button and CrescoHelp popup

  - A HELP button on every page: bottom right on desktop, just above the tab
    bar on mobile. It opens a branded CrescoHelp popup showing the help pages
    (full screen sheet on phones), with an "Open in a new tab" link.
  - The help pages now use Crescopus fonts and colours (new
    app/static/css/crescohelp.css).
  - The help address is now /content/help (uses modcontent v0.2.4).
  - Visitors who are not logged in can use CrescoHelp too. AI matching stays
    limited to 20 questions an hour per person.

BEFORE YOU RUN THIS
  Run apply_modcontent_help_page.py in modcontent and push the v0.2.4 tag first.

HOW TO USE
  1. Save this file in your Crescopus project folder (next to wsgi.py).
  2. In PowerShell, in that folder, with your venv active:
         python apply_help_button.py
         pip install -r requirements.txt
  3. Restart python wsgi.py and press Ctrl+F5 in the browser.
  4. Any file it replaces is copied first to _backup_apply_help_button\.

It checks each file matches the version on GitHub first. If you have changed
one locally since your last push, it stops without writing anything.
Your .env is never read or changed.
"""
import base64, hashlib, os, shutil, sys

# (path, new content, sha256s of the versions it may replace)
FILES = [
    ('app/__init__.py', '', ['ecea3b47c9eeee0646e67b464d92904a81ef63e8a448d4e0bd547caf938e3c14']),
    ('requirements.txt', '', ['898a3d96f10d1cfd53396ce1f8f5a6426b1457e8ec0a9d7375e6b8900c6cf78d']),
    ('app/templates/base.html', '', ['e337fb7e17158b4d5444a5271491069b46dd90fce31cfa831997b6f08cba700b']),
    ('app/static/css/cresco-ui.css', '', ['bfef37e51a4012001e018d8396dec4b71eb9faa36fffe232a5bad44e3e429b8e']),
    ('app/static/css/crescohelp.css', '', []),
]
BACKUP = '_backup_apply_help_button'
NEXT = 'pip install -r requirements.txt, restart python wsgi.py (Ctrl+F5 in the browser), test, then commit and push.'

def sha(data):
    return hashlib.sha256(data).hexdigest()

def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if not (os.path.isfile(os.path.join(root, *['wsgi.py'])) and os.path.isfile(os.path.join(root, *['app', '__init__.py']))):
        sys.exit("Stopped: put this file in the Crescopus project folder, then run it again.")
    clashes = []
    for rel, b64, expected in FILES:
        path = os.path.join(root, *rel.split("/"))
        if not os.path.exists(path):
            continue
        new = base64.b64decode(b64)
        with open(path, "rb") as fh:
            current = fh.read()
        current_norm = current.replace(b"\r\n", b"\n")
        if current == new or current_norm == new:
            continue
        if not expected or sha(current_norm) not in expected:
            clashes.append(rel)
    if clashes:
        print("Stopped - nothing written. These files differ from the version this update was built from:")
        for c in clashes:
            print("   " + c)
        sys.exit("Push or share your latest changes and ask for the update to be rebuilt.")

    backup = os.path.join(root, BACKUP)
    changed = 0
    for rel, b64, expected in FILES:
        path = os.path.join(root, *rel.split("/"))
        data = base64.b64decode(b64)
        status = "new     "
        if os.path.exists(path):
            with open(path, "rb") as fh:
                current = fh.read()
            if current == data or current.replace(b"\r\n", b"\n") == data:
                print("same     " + rel)
                continue
            dest = os.path.join(backup, *rel.split("/"))
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            shutil.copy2(path, dest)
            status = "updated "
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(data)
        changed += 1
        print(status + " " + rel)
    print("\nDone - %d of %d files written." % (changed, len(FILES)))
    if os.path.isdir(backup):
        print("Originals of replaced files are in " + BACKUP + os.sep)
    if NEXT:
        print("Next: " + NEXT)

if __name__ == "__main__":
    main()
